int tcp_disconnect(struct sock *sk, int flags) {
    int err = 0;

    if (sk == NULL) {
        return -EINVAL;
    }

    if (sk->sk_state != TCP_CLOSE) {
        sk->sk_state = TCP_CLOSE;

        switch (sk->sk_state) {
            case TCP_LISTEN: {
                sk->sk_state = TCP_CLOSE;
                break;
            }
            case TCP_SYN_SENT: {
                break;
            }
            case TCP_ESTABLISHED: {
                if (flags & TCP_SEND_RESET) {
                    // Send a reset packet
                    // Implementation of sending a reset packet would go here
                }
                break;
            }
            default: {
                break;
            }
        }

        // Purge transmit and receive queues
        skb_queue_purge(&sk->sk_write_queue);
        skb_queue_purge(&sk->sk_receive_queue);

        // Reset TCP parameters
        sk->sk_rcvbuf = 0;
        sk->sk_sndbuf = 0;
        sk->sk_reuse = 0;
        sk->sk_lingertime = 0;

        // Clean up fastopen-related fields
        sk->sk_fastopen_queue = NULL;
    }

    return err;
}
